"""Per-tick bird physics (spec/02_physics.md)."""

from units import BIRD_H, FIELD_H, FLAP_V, G, VY_MAX


def step_bird(y, vy, flap):
    """Advance the bird one tick; return (y, vy, alive)."""
    alive = True
    if flap:
        vy = FLAP_V
    else:
        vy = min(vy + G, VY_MAX)
    y += vy
    if y < 0:
        y = 0
        vy = 0
    if y + BIRD_H > FIELD_H:
        y = FIELD_H - BIRD_H
        alive = False
    return (y, vy, alive)

"""LCG pipe generator and pipe motion (spec/03_world.md)."""

from units import PIPE_W, SCROLL, SPAWN_EVERY, SPAWN_X


def lcg(s):
    """Advance the LCG state once; return the new state."""
    return (1103515245 * s + 12345) % 2147483648


def spawn(t, s):
    """On a spawn tick return (pipe, new_s); otherwise (None, s)."""
    if t % SPAWN_EVERY != 0:
        return None, s
    s = lcg(s)
    gap_top = 40 + (s >> 8) % 80
    return {"x": SPAWN_X, "gap_top": gap_top, "passed": False}, s


def scroll(pipes):
    """Move every pipe left by SCROLL; return the list."""
    for p in pipes:
        p["x"] -= SCROLL
    return pipes


def cull(pipes):
    """Drop every pipe with x + PIPE_W <= 0; return the survivors."""
    return [p for p in pipes if p["x"] + PIPE_W > 0]

"""The deterministic per-tick run loop (specs 02-05). Integers only."""

import collide
import physics
import units
import world


def run(seed, ticks, flaps, powerups=False, trace=None):
    """Simulate a run; return the final state as a dict.

    If trace is not None it is called as trace(t, y, vy, score, alive)
    at the end of every executed tick, after culling.
    """
    if powerups:
        raise NotImplementedError("power-ups are future work (spec/07)")
    y, vy = 560, 0
    score, s, alive = 0, seed, True
    pipes, ticks_run = [], 0
    for t in range(ticks):
        if not alive:
            break
        pipe, s = world.spawn(t, s)                    # 1. SPAWN
        if pipe is not None:
            pipes.append(pipe)
        y, vy, alive = physics.step_bird(y, vy, flaps[t % len(flaps)] == "1")  # 2. PHYSICS
        world.scroll(pipes)                            # 3. SCROLL
        for p in pipes:                                # 4. COLLIDE
            if collide.pipe_hit(y, p):
                alive = False
                break
        if alive:                                      # 5. SCORE (fatal tick scores nothing)
            for p in pipes:
                if not p["passed"] and p["x"] + units.PIPE_W <= units.BIRD_X:
                    p["passed"] = True
                    score += 1
                    if abs(vy) <= units.GLIDE_VY:
                        score += 1
        pipes = world.cull(pipes)                      # 6. CULL
        ticks_run = t + 1                              # 7. HALT
        if trace is not None:
            trace(t, y, vy, score, alive)
    return {"y": y, "vy": vy, "score": score, "alive": alive, "ticks_run": ticks_run}

"""flapsim command line and output format (spec/06_cli.md)."""

import sys

import engine

CASES = [(7, 200, "0010", 8, 1), (7, 120, "01", 0, 0),
         (3, 200, "0001", 8, 1), (11, 60, "1", 0, 0),
         (2, 90, "0", 0, 0), (5, 200, "0010", 8, 1)]


def parse(argv):
    o = {"seed": None, "ticks": None, "flaps": "0", "powerups": False}
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--powerups":
            o["powerups"] = True
            i += 1
        elif a in ("--seed", "--ticks", "--flaps"):
            v = argv[i + 1]
            o[a[2:]] = int(v) if a != "--flaps" else v
            i += 2
        else:
            raise ValueError("unknown argument: " + a)
    return o


def selfcheck():
    for n, (seed, ticks, flaps, ws, wa) in enumerate(CASES, 1):
        st = engine.run(seed, ticks, flaps)
        ok = st["score"] == ws and bool(st["alive"]) == bool(wa)
        print("EX%d seed=%d ticks=%d flaps=%s expect score=%02d alive=%d "
              "got score=%02d alive=%d %s" % (n, seed, ticks, flaps, ws, wa,
                                              st["score"], int(st["alive"]),
                                              "OK" if ok else "FAIL"))


def main(argv):
    if "--selfcheck" in argv:
        selfcheck()
        return 0
    o = parse(argv)
    if o["seed"] is None or o["ticks"] is None or not o["flaps"]:
        print("error: usage: flapsim.py --seed S --ticks N --flaps BITS", file=sys.stderr)
        return 2
    every = max(1, o["ticks"] // 20)

    def trace(t, y, vy, score, alive):
        if t % every == 0:
            print("TRACE t=%04d y=%04d vy=%+05d score=%02d alive=%d" % (t, y, vy, score, int(alive)))

    st = engine.run(o["seed"], o["ticks"], o["flaps"], o["powerups"], trace)
    d = "DIGEST seed=%d ticks=%d score=%d alive=%d y=%04d vy=%+05d ticks_run=%d" % (
        o["seed"], o["ticks"], st["score"], int(st["alive"]), st["y"], st["vy"], st["ticks_run"])
    if o["powerups"]:
        d += " shields=%d" % st["shields"]
    print(d)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

